const readline = require('readline');
const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
  terminal: false
});
let c = 0;

rl.on('line', (d) => {
  if (c === 0) {
    c++;
    return;
  }

  const arr = d.split(' ').map(Number);
  arr.sort((a, b) => a - b);
  let ans = 0;
  let prev = -1;

  for (let i = 0; i < arr.length; i++) {
    if (prev !== arr[i] && arr[i] !== 0) {
      ans++;
      prev = arr[i];
    }
  }

  console.log(ans);

  c++;
});
